      if(patch.width!==undefined){r.rightOfWay=patch.width;if(r.boundaryAlignment){r.path=roadOutsideBoundary(next.boundary,r.boundaryAlignment,patch.width);r.a=r.path[0];r.b=r.path[1];if(r.eligible.length)r.eligible=adjacentFrontages(next,r);}}
      if(patch.permit!==undefined)r.eligible=patch.permit?adjacentFrontages(next,r):[];if(patch.width!==undefined||patch.permit!==undefined)repairEntrances(next,id);setDraft(next);setPreparation(null);
