  const keepAlternative=()=>{if(!workspace||workspace.alternatives.length>=20)return;const id=`scheme_${Date.now()}`,s=structuredClone(workspace.accepted);s.id=id;s.name=`${name} · ${workspace.alternatives.length+1}`;s.result=buildResidentialScenario(s.inputs,id,s.name).result;store({...workspace,alternatives:[...workspace.alternatives,s]},'Saved independent residential alternative');};
  const runSearch=()=>{if(!workspace||dirty||searching)return;setSearching(true);const worker=residentialCalculationWorker();searchWorker.current=worker;worker.postMessage({kind:'search',base:workspace.accepted,allocationsOnly:false});worker.onerror=()=>{setSearching(false);worker.terminate();setStatus('Alternative search failed; accepted scenario preserved.');};worker.onmessage=event=>{setSearching(false);worker.terminate();if(!event.data.ok){setStatus(event.data.error);return;}const found=event.data.value as ReturnType<typeof searchResidential>;setSearch({tested:found.tested,conflicts:found.conflicts});const alternatives=[...workspace.alternatives];for(const s of found.candidates){s.id=`search_${Date.now()}_${s.id}`;s.result=buildResidentialScenario(s.inputs,s.id,s.name).result;if(!alternatives.some(a=>JSON.stringify(a.inputs)===JSON.stringify(s.inputs)))alternatives.push(s);}store({...workspace,alternatives:alternatives.slice(-20)},`Tested ${found.tested} bounded spatial/allocation alternatives; retained ${found.candidates.length}`);setTab('alternatives');};};
